d; \nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.apply_unified_student_grade_import(p_mutation_id text, p_device_id text, p_batch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\r\ndeclare\r\n  v_owner uuid:=auth.uid(); v_saved rakeezx.score_domain_receipts%rowtype;\r\n  v_envelope jsonb; v_result jsonb; v_teaching rakeezx.teachings%rowtype;\r\n  v_new jsonb; v_roll int; v_key text; v_ids text[]:=''{}''; v_enrollment_ids text[]:=''{}'';\r\nbegin\r\n  if v_owner is null then raise exception using errcode=''42501'',message=''Authentication required''; end if;\r\n  if coalesce(length(p_mutation_id),0) not between 1 and 200 or coalesce(length(p_device_id),0) not between 1 and 200 or\r\n    jsonb_typeof(p_batch) is distinct from ''object'' or jsonb_typeof(p_batch->''newStudents'') is distinct from ''array'' or\r\n    jsonb_typeof(p_batch->''cells'') is distinct from ''array'' or jsonb_typeof(p_batch->''newItems'') is distinct from ''array'' or\r\n    p_batch->>''enrollmentConfirmed'' is distinct from ''true'' then\r\n    raise exception using errcode=''22023'',message=''Explicit reviewed enrollment required''; end if;\r\n  if jsonb_array_length(p_batch->''newStudents'') not between 1 and 300 or jsonb_array_length(p_batch->''cells'')>15000 or\r\n    (select count(distinct id) from (select x->>''id'' id from jsonb_array_elements(p_batch->''newStudents'') x union all select x->>''studentId'' from jsonb_array_elements(p_batch->''cells'') x) identities)>300 or\r\n    (select count(distinct x->>''id'') from jsonb_array_elements(p_batch->''newStudents'') x)<>jsonb_array_length(p_batch->''newStudents'') or\r\n    (select count(distinct x->>''enrollmentId'') from jsonb_array_elements(p_batch->''newStudents'') x)<>jsonb_array_length(p_batch->''newStudents'') or\r\n    (select count(distinct lower(regexp_replace(normalize(x->>''name'',NFC),''[[:space:]ـً-ٰٟ]'','''',''g''))) from jsonb_array_elements(p_batch->''newStudents'') x)<>jsonb_array_length(p_batch->''newStudents'') then\r\n    raise exception using errcode=''22023'',message=''Duplicate or oversized new students''; end if;\r\n  perform rakeezx.lock_student_lifecycle(v_owner);\r\n  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||'':score-domain-receipt:''||p_mutation_id,0));\r\n  v_envelope:=jsonb_build_object(''protocol'',''N90_UNIFIED_V1'',''deviceId'',p_device_id,''batch'',p_batch);\r\n  select * into v_saved from rakeezx.score_domain_receipts where owner_id=v_owner and mutation_id=p_mutation_id;\r\n  if found then\r\n    if v_saved.request_envelope is distinct from v_envelope then raise exception using errcode=''22023'',message=''Unified mutation ID reused''; end if;\r\n    return v_saved.result;\r\n  end if;\r\n  select * into v_teaching from rakeezx.teachings where owner_id=v_owner and id=p_batch->>''teachingId'' and deleted_at is null for update;\r\n  if v_teaching.id is null or v_teaching.section_id is distinct from p_batch->>''sectionId'' or\r\n    v_teaching.revision is distinct from (p_batch->>''teachingRevision'')::bigint or v_teaching.term_id is distinct from p_batch->>''termId'' or not exists (\r\n      select 1 from rakeezx.sections s join rakeezx.terms t on t.owner_id=s.owner_id and t.year_id=s.year_id\r\n      join rakeezx.years y on y.owner_id=s.owner_id and y.id=s.year_id\r\n      join rakeezx.subjects u on u.owner_id=s.owner_id and u.id=v_teaching.subject_id\r\n      where s.owner_id=v_owner and s.id=v_teaching.section_id and t.id=v_teaching.term_id and s.deleted_at is null\r\n        and t.deleted_at is null and y.deleted_at is null and u.deleted_at is null and s.status<>''archived'' and t.status=''active'' and y.status=''active'') then\r\n    raise exception using errcode=''PT409'',message=''Teaching or current term changed''; end if;\r\n  select coalesce(max(roll_no),0) into v_roll from rakeezx.enrollments where owner_id=v_owner and section_id=v_teaching.section_id and status=''active'' and deleted_at is null;\r\n  if v_roll+jsonb_array_length(p_batch->''newStudents'')>999 then raise exception using errcode=''22023'',message=''Roster limit''; end if;\r\n  for v_new in select value from jsonb_array_elements(p_batch->''newStudents'') order by value->>''enrollmentId'' loop\r\n    if jsonb_typeof(v_new->''id'') is distinct from ''string'' or jsonb_typeof(v_new->''enrollmentId'') is distinct from ''string'' or jsonb_typeof(v_new->''name'') is distinct from ''string'' or\r\n      coalesce(length(v_new->>''id''),0) not between 1 and 200 or coalesce(length(v_new->>''enrollmentId''),0) not between 1 and 200 or\r\n      coalesce(length(btrim(v_new->>''name'')),0) not between 2 and 80 or v_new->>''name'' is distinct from btrim(v_new->>''name'') or\r\n      v_new->>''name'' ~ (''^[=+@-]|[[:cntrl:]''||chr(8203)||''-''||chr(8207)||chr(8234)||''-''||chr(8238)||chr(8294)||''-''||chr(8297)||'']'') or\r\n      regexp_replace(v_new->>''name'',''[0-9٠-٩۰-۹[:space:][:punct:]]'','''',''g'')=''''  then\r\n      raise exception using errcode=''22023'',message=''Invalid student identity or name''; end if;\r\n    -- Existing/deleted identities are never resurrected or adopted by name.\r\n    if exists(select 1 from rakeezx.students where owner_id=v_owner and id=v_new->>''id'') or\r\n      exists(select 1 from rakeezx.enrollments where owner_id=v_owner and id=v_new->>''enrollmentId'') then\r\n      raise exception using errcode=''PT409'',message=''New identity already exists''; end if;\r\n    v_key:=lower(regexp_replace(normalize(v_new->>''name'',NFC),''[[:space:]ـً-ٰٟ]'','''',''g''));\r\n    if exists(select 1 from rakeezx.students s join rakeezx.enrollments e on e.owner_id=s.owner_id and e.student_id=s.id\r\n      where s.owner_id=v_owner and s.deleted_at is null and e.deleted_at is null and e.status=''active'' and e.section_id=v_teaching.section_id and\r\n      lower(regexp_replace(normalize(s.name,NFC),''[[:space:]ـً-ٰٟ]'','''',''g''))=v_key) then\r\n      raise exception using errcode=''PT409'',message=''Roster changed since review''; end if;\r\n    insert into rakeezx.students(owner_id,id,name,device_id) values(v_owner,v_new->>''id'',v_new->>''name'',p_device_id);\r\n    v_roll:=v_roll+1;\r\n    insert into rakeezx.enrollments(owner_id,id,student_id,section_id,roll_no,device_id)\r\n      values(v_owner,v_new->>''enrollmentId'',v_new->>''id'',v_teaching.section_id,v_roll,p_device_id);\r\n    v_ids:=array_append(v_ids,v_new->>''id''); v_enrollment_ids:=array_append(v_enrollment_ids,v_new->>''enrollmentId'');\r\n  end loop;\r\n  if jsonb_array_length(p_batch->''cells'')>0 then\r\n    -- Nested function has no independent transaction. Any late grade failure rolls back enrollment too.\r\n    v_result:=rakeezx.apply_reviewed_grade_import(p_mutation_id,p_device_id,p_batch-''newStudents''-''sectionId''-''enrollmentConfirmed'');\r\n  else\r\n    if jsonb_array_length(p_batch->''newItems'')<>0 then raise exception using errcode=''22023'',message=''Unused new items''; end if;\r\n    v_result:=jsonb_build_object(''mutationId'',p_mutation_id,''teachingId'',v_teaching.id,''items'',''[]''::jsonb,''scores'',''[]''::jsonb,''score_subitems'',''[]''::jsonb,''score_subitem_completions'',''[]''::jsonb);\r\n  end if;\r\n  v_result:=v_result || jsonb_build_object(''protocol'',''N90_UNIFIED_V1'',\r\n    ''students'',(select jsonb_agg(to_jsonb(s) order by id) from rakeezx.students s where owner_id=v_owner and id=any(v_ids)),\r\n    ''enrollments'',(select jsonb_agg(to_jsonb(e) order by id) from rakeezx.enrollments e where owner_id=v_owner and id=any(v_enrollment_ids)));\r\n  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result) values(v_owner,p_mutation_id,v_envelope,v_result)\r\n    on conflict(owner_id,mutation_id) do update set request_envelope=excluded.request_envelope,result=excluded.result;\r\n  return v_result;\r\nend; \nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.finalize_n71_restore(p_restore_id text, p_backup_hash text, p_expected_stage_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\ndeclare v_owner uuid:=auth.uid(); v_stage rakeezx.sync_restore_stages%rowtype;\n  v_receipt rakeezx.sync_restore_receipts%rowtype; v_operation jsonb;\n  v_entity text; v_id text; v_action text; v_patch jsonb; v_columns text; v_values text;\n  v_calendar record; v_year record; v_sets text; v_field text; v_sql text; v_row jsonb; v_canonical jsonb; v_result jsonb;\nbegin\n  if v_owner is null then raise exception using errcode=''42501'',message=''Authentication required''; end if;\n  perform rakeezx.lock_student_lifecycle(v_owner);\n  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||'':restore:''||p_restore_id,0));\n  select * into v_receipt from rakeezx.sync_restore_receipts where owner_id=v_owner and restore_id=p_restore_id;\n  if found then\n    if (v_receipt.backup_hash,v_receipt.stage_hash) is distinct from\n      (p_backup_hash,p_expected_stage_hash) then\n      raise exception using errcode=''22023'',message=''V5 restore receipt mismatch''; end if;\n    if v_receipt.result->>''protocol'' is distinct from ''N71_V1'' then\n      raise exception using errcode=''22023'',message=''N71 receipt protocol mismatch''; end if;\n    return v_receipt.result;\n  end if;\n  select * into v_stage from rakeezx.sync_restore_stages\n    where owner_id=v_owner and restore_id=p_restore_id for update;\n  if not found or v_stage.backup_version not in (3,4,5) or\n    (v_stage.backup_hash,v_stage.stage_hash) is distinct from\n      (p_backup_hash,p_expected_stage_hash) then\n    raise exception using errcode=''22023'',message=''V5 restore stage mismatch''; end if;\n  if v_stage.source_manifest is distinct from rakeezx.n71_restore_manifest(v_owner) then\n    raise exception using errcode=''40001'',message=''Canonical source changed after V5 staging''; end if;\n  insert into rakeezx.n58_restore_transactions values(v_owner,pg_catalog.txid_current(),p_restore_id);\n  perform pg_catalog.set_config(''rakeezx.sync_v2_attendance_snapshot'',''on'',true);\n  perform pg_catalog.set_config(''rakeezx.section_lifecycle_write'',''on'',true);\n  perform pg_catalog.set_config(''rakeezx.section_lifecycle_delete'',''on'',true);\n  perform pg_catalog.set_config(''rakeezx.score_domain_write'',''on'',true);\n  for v_operation in select value from pg_catalog.jsonb_array_elements(v_stage.operations) loop\n    v_entity:=v_operation->>''entity''; v_id:=v_operation->>''recordId'';\n    v_action:=v_operation->>''operation''; v_patch:=coalesce(v_operation->''patch'',''{}''::jsonb);\n    v_columns:=''''; v_values:=''''; v_sets:='''';\n    if v_entity=''profile'' then\n      select pg_catalog.to_jsonb(t) into v_row from rakeezx.profile t where owner_id=v_owner for update;\n    else\n      execute pg_catalog.format(''select pg_catalog.to_jsonb(t) from rakeezx.%I t\n        where owner_id=$1 and id=$2 for update'',v_entity) into v_row using v_owner,v_id;\n    end if;\n    if (v_action in (''create'',''create_deleted'') and v_row is not null) or\n      (v_action not in (''create'',''create_deleted'') and\n        (v_row is null or (v_row->>''deleted_at'') is not null or\n        (v_row->>''revision'')::bigint<>(v_operation->>''baseRevision'')::bigint)) then\n      raise exception using errcode=''40001'',message=''Canonical source changed during V5 finalize''; end if;\n    if v_action not in (''delete'',''create_deleted'') then\n      perform rakeezx.n71_assert_restore_scope(v_owner,v_entity,\n        coalesce(v_row,''{}''::jsonb)||v_patch||jsonb_build_object(''id'',v_id),v_stage.source_manifest);\n    end if;\n    if v_action in (''create'',''create_deleted'') then\n      for v_field in select pg_catalog.jsonb_object_keys(v_patch) order by 1 loop\n        v_columns:=v_columns||pg_catalog.format('',%I'',v_field);\n        v_values:=v_values||pg_catalog.format('',p.%I'',v_field);\n      end loop;\n      if v_action=''create_deleted'' then\n        v_columns:=v_columns||'',deleted_at'';\n        v_values:=v_values||'',pg_catalog.clock_timestamp()'';\n      end if;\n      if v_entity=''profile'' then\n        v_sql:=pg_catalog.format(''insert into rakeezx.profile(owner_id,device_id,client_updated_at%s)\n          select $1,$2,$3%s from pg_catalog.jsonb_populate_record(null::rakeezx.profile,$4) p'',v_columns,v_values);\n        execute v_sql using v_owner,''restore:''||p_restore_id,(v_operation->>''clientUpdatedAt'')::bigint,v_patch;\n      else\n        v_sql:=pg_catalog.format(''insert into rakeezx.%I(owner_id,id,device_id,client_updated_at%s)\n          select $1,$2,$3,$4%s from pg_catalog.jsonb_populate_record(null::rakeezx.%I,$5) p'',\n          v_entity,v_columns,v_values,v_entity);\n        execute v_sql using v_owner,v_id,''restore:''||p_restore_id,\n          (v_operation->>''clientUpdatedAt'')::bigint,v_patch;\n      end if;\n    elsif v_action=''delete'' then\n      if v_entity=''profile'' then\n        update rakeezx.profile set deleted_at=pg_catalog.clock_timestamp(),\n          device_id=''restore:''||p_restore_id where owner_id=v_owner;\n      else\n        execute pg_catalog.format(''update rakeezx.%I set deleted_at=pg_catalog.clock_timestamp(),\n          device_id=$1 where owner_id=$2 and id=$3'',v_entity)\n          using ''restore:''||p_restore_id,v_owner,v_id;\n      end if;\n    else\n      for v_field in select pg_catalog.jsonb_object_keys(v_patch) order by 1 loop\n        if v_sets<>'''' then v_sets:=v_sets||'',''; end if;\n        v_sets:=v_sets||pg_catalog.format(''%I=(select p.%I from pg_catalog.jsonb_populate_record(null::rakeezx.%I,$1) p)'',\n          v_field,v_field,v_entity);\n      end loop;\n      if v_sets='''' then continue; end if;\n      v_sets:=v_sets||'',device_id=$2,client_updated_at=$3'';\n      if v_entity=''profile'' then\n        execute ''update rakeezx.profile set ''||v_sets||'' where owner_id=$4''\n          using v_patch,''restore:''||p_restore_id,(v_operation->>''clientUpdatedAt'')::bigint,v_owner;\n      else\n        execute pg_catalog.format(''update rakeezx.%I set %s where owner_id=$4 and id=$5'',v_entity,v_sets)\n          using v_patch,''restore:''||p_restore_id,(v_operation->>''clientUpdatedAt'')::bigint,v_owner,v_id;\n      end if;\n    end if;\n  end loop;\n  for v_year in select y.* from rakeezx.years y where y.owner_id=v_owner\n    and y.calendar_preset_id is not null and rakeezx.n58_restore_creating_year(v_owner,y.id) loop\n    if (select count(*) from rakeezx.terms t where t.owner_id=v_owner and t.year_id=v_year.id\n      and t."index" in (1,2) and t.deleted_at is null)<>2 then\n      raise exception using errcode=''22023'',message=''N58_EXISTING_TERMS_REQUIRED''; end if;\n  end loop;\n  for v_calendar in select c.* from rakeezx.calendars c where c.owner_id=v_owner\n    and rakeezx.n58_restore_creating_year(v_owner,c.year_id) loop\n    perform rakeezx.n58_validate_overrides(v_owner,v_calendar.year_id,v_calendar.preset_id,v_calendar.term_date_overrides);\n  end loop;\n  delete from rakeezx.n58_restore_transactions where owner_id=v_owner and transaction_id=pg_catalog.txid_current();\n  perform rakeezx.assert_score_provenance_consistent(v_owner);\n  if exists(select 1 from rakeezx.scores s join rakeezx.items i\n    on i.owner_id=s.owner_id and i.id=s.item_id where s.owner_id=v_owner\n    and s.deleted_at is null and i.deleted_at is null and (s.value<0 or s.value>i.max)) then\n    raise exception using errcode=''22023'',message=''N71 score exceeds current target maximum''; end if;\n  v_canonical:=rakeezx.n71_restore_canonical(v_owner);\n  v_result:=pg_catalog.jsonb_build_object(''protocol'',''N71_V1'',''restoreId'',p_restore_id,''backupHash'',p_backup_hash,\n    ''stageHash'',p_expected_stage_hash,\n    ''receipt'',pg_catalog.jsonb_build_object(''restoreId'',p_restore_id,''status'',''finalized''),\n    ''canonical'',v_canonical);\n  insert into rakeezx.sync_restore_receipts(owner_id,restore_id,backup_hash,stage_hash,result)\n    values(v_owner,p_restore_id,p_backup_hash,p_expected_stage_hash,v_result);\n  update rakeezx.sync_restore_stages set state=''finalized'',finalized_at=pg_catalog.clock_timestamp()\n    where owner_id=v_owner and restore_id=p_restore_id;\n  return v_result;\nend; \nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.finalize_sync_v2_restore(p_restore_id text, p_backup_hash text, p_expected_stage_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\r\n      declare v_owner uuid:=auth.uid(); v_result jsonb; v_calendar record; v_year record;\r\n      begin\r\n        if v_owner is null then raise exception using errcode=''42501'',message=''Authentication required''; end if;\r\n        perform rakeezx.lock_student_lifecycle(v_owner);\r\n        insert into rakeezx.n58_restore_transactions values(v_owner,pg_catalog.txid_current(),p_restore_id);\r\n        v_result:=rakeezx.finalize_sync_v2_restore_before_n58(p_restore_id,p_backup_hash,p_expected_stage_hash);\r\n        for v_year in select y.* from rakeezx.years y where y.owner_id=v_owner\r\n          and y.calendar_preset_id is not null and rakeezx.n58_restore_creating_year(v_owner,y.id) loop\r\n          if (select count(*) from rakeezx.terms t where t.owner_id=v_owner and t.year_id=v_year.id\r\n            and t."index" in (1,2) and t.deleted_at is null)<>2 then\r\n            raise exception using errcode=''22023'',message=''N58_EXISTING_TERMS_REQUIRED''; end if;\r\n        end loop;\r\n        -- Calendar->term FK ordering requires calendars before terms. Validate\r\n        -- fresh-year override references AFTER all checked restore operations;\r\n        -- any error rolls back the domain rows AND the existing receipt.\r\n        for v_calendar in select c.* from rakeezx.calendars c where c.owner_id=v_owner\r\n          and rakeezx.n58_restore_creating_year(v_owner,c.year_id) loop\r\n          perform rakeezx.n58_validate_overrides(v_owner,v_calendar.year_id,v_calendar.preset_id,v_calendar.term_date_overrides);\r\n        end loop;\r\n        delete from rakeezx.n58_restore_transactions where owner_id=v_owner and transaction_id=pg_catalog.txid_current();\r\n        return v_result;\r\n      end; \nEND; ';
