All N77 scope transitions serialize on the owner/Section row.\r\n  select * into v_section from rakeezx.sections\r\n    where owner_id=v_owner and id=p_expected_section_id for update;\r\n  if not found or v_section.deleted_at is not null then\r\n    raise exception using errcode=''22023'',message=''N77 scope is stale'';\r\n  end if;\r\n  select * into v_teaching from rakeezx.teachings\r\n    where owner_id=v_owner and id=p_teaching_id and section_id=v_section.id for update;\r\n  if not found or v_teaching.deleted_at is not null then\r\n    raise exception using errcode=''22023'',message=''N77 scope is stale'';\r\n  end if;\r\n  select pg_catalog.array_agg(id order by id) into v_ids from rakeezx.teachings\r\n    where owner_id=v_owner and section_id=v_section.id and deleted_at is null;\r\n  if v_ids is null or not (p_teaching_id=any(v_ids)) then\r\n    raise exception using errcode=''22023'',message=''N77 scope is stale'';\r\n  end if;\r\n  v_scope := case when pg_catalog.array_length(v_ids,1)>1 then ''teaching'' else ''section'' end;\r\n  -- A changed sibling set, selected row or Section invalidates the shown confirmation.\r\n  select pg_catalog.md5(v_owner::text||'':''||v_section.id||'':''||v_section.revision::text||'':''||\r\n    pg_catalog.string_agg(t.id||'':''||t.revision::text,'','' order by t.id)) into v_fingerprint\r\n    from rakeezx.teachings t where t.owner_id=v_owner and t.section_id=v_section.id and t.deleted_at is null;\r\n  if p_commit and p_expected_fingerprint<>v_fingerprint then\r\n    raise exception using errcode=''22023'',message=''N77 scope is stale'';\r\n  end if;\r\n  if v_scope=''teaching'' then v_ids := array[p_teaching_id]; end if;\r\n  v_result := pg_catalog.jsonb_build_object(''ownerId'',v_owner,''sectionId'',v_section.id,\r\n    ''selectedTeachingId'',p_teaching_id,''scope'',v_scope,''teachingIds'',pg_catalog.to_jsonb(v_ids),\r\n    ''fingerprint'',v_fingerprint);\r\n  if not p_commit then return v_result; end if;\r\n\r\n  -- A final Section Delete also closes live descendants of historical Teaching\r\n  -- tombstones created by older lifecycle code. The confirmation still names\r\n  -- only the final active Teaching.\r\n  if v_scope=''section'' then\r\n    select pg_catalog.array_agg(id order by id) into v_ids from rakeezx.teachings\r\n      where owner_id=v_owner and section_id=v_section.id;\r\n  end if;\r\n  v_result := v_result || pg_catalog.jsonb_build_object(''cascadeTeachingIds'',pg_catalog.to_jsonb(v_ids));\r\n\r\n  -- Student identity is shared and local-only assignments/submissions are not\r\n  -- visible to this server. Preserve every student identity; removing the\r\n  -- Section enrollment makes an otherwise unreferenced student invisible in UX.\r\n\r\n  perform pg_catalog.set_config(''rakeezx.section_lifecycle_delete'',''on'',true);\r\n  perform pg_catalog.set_config(''rakeezx.score_domain_write'',''on'',true);\r\n  -- Descendants first. Every update and receipt shares this RPC transaction.\r\n  update rakeezx.score_subitem_completions c set deleted_at=v_now,device_id=p_device_id\r\n    where c.owner_id=v_owner and c.deleted_at is null and (\r\n      c.subitem_id in (select si.id from rakeezx.score_subitems si join rakeezx.items i\r\n        on i.owner_id=si.owner_id and i.id=si.item_id where si.owner_id=v_owner and i.teaching_id=any(v_ids))\r\n      or c.student_id=any(v_orphans));\r\n  update rakeezx.score_subitems si set deleted_at=v_now,device_id=p_device_id\r\n    where si.owner_id=v_owner and si.deleted_at is null and si.item_id in\r\n      (select id from rakeezx.items where owner_id=v_owner and teaching_id=any(v_ids));\r\n  update rakeezx.scores s set deleted_at=v_now,device_id=p_device_id\r\n    where s.owner_id=v_owner and s.deleted_at is null and (s.student_id=any(v_orphans) or s.item_id in\r\n      (select id from rakeezx.items where owner_id=v_owner and teaching_id=any(v_ids)));\r\n  update rakeezx.attendance a set deleted_at=v_now,device_id=p_device_id\r\n    where a.owner_id=v_owner and a.deleted_at is null and (a.student_id=any(v_orphans) or\r\n      a.teaching_id=any(v_ids) or a.session_id in\r\n      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));\r\n  update rakeezx.session_roster_snapshots s set deleted_at=v_now,device_id=p_device_id\r\n    where s.owner_id=v_owner and s.deleted_at is null and (s.teaching_id=any(v_ids) or\r\n      s.session_id in (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)) or\r\n      (v_scope=''section'' and s.section_id=v_section.id));\r\n  update rakeezx.logs l set deleted_at=v_now,device_id=p_device_id\r\n    where l.owner_id=v_owner and l.deleted_at is null and (l.student_id=any(v_orphans) or\r\n      l.teaching_id=any(v_ids) or l.session_id in\r\n      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));\r\n  update rakeezx.notes n set deleted_at=v_now,device_id=p_device_id\r\n    where n.owner_id=v_owner and n.deleted_at is null and (n.student_id=any(v_orphans) or\r\n      n.teaching_id=any(v_ids) or n.session_id in\r\n      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));\r\n  update rakeezx.class_goals set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);\r\n  update rakeezx.class_charter_selections set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);\r\n  update rakeezx.group_arrangements set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);\r\n  update rakeezx.class_rules set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);\r\n  update rakeezx.slots set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);\r\n  update rakeezx.sessions set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);\r\n  update rakeezx.items set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);\r\n  update rakeezx.teachings set deleted_at=v_now,device_id=p_device_id\r\n    where owner_id=v_owner and deleted_at is null and id=any(v_ids);\r\n  if v_scope=''section'' then\r\n    update rakeezx.enrollments set deleted_at=v_now,device_id=p_device_id\r\n      where owner_id=v_owner and deleted_at is null and section_id=v_section.id;\r\n    update rakeezx.students set deleted_at=v_now,device_id=p_device_id\r\n      where owner_id=v_owner and deleted_at is null and id=any(v_orphans);\r\n    update rakeezx.sections set deleted_at=v_now,device_id=p_device_id\r\n      where owner_id=v_owner and deleted_at is null and id=v_section.id;\r\n  end if;\r\n  v_result := v_result || pg_catalog.jsonb_build_object(''mutationId'',p_mutation_id,\r\n    ''outcome'',''deleted'',''orphanStudentIds'',pg_catalog.to_jsonb(v_orphans));\r\n  insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,\r\n    base_revision,operation,request_patch,request_envelope,outcome,applied_groups,\r\n    conflicted_groups,result)\r\n  values(v_owner,p_mutation_id,''lifecycle'',p_teaching_id,p_device_id,0,''lifecycle'',''{}''::jsonb,\r\n    v_envelope,''deleted'',array[''__deleted__'']::text[],array[]::text[],v_result);\r\n  return v_result;\r\nend; \nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.commit_enrollment_transfer(p_source jsonb, p_destination jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\r\ndeclare\r\n  v_owner uuid := auth.uid();\r\n  v_source_id text := p_source ->> ''id'';\r\n  v_destination_id text := p_destination ->> ''id'';\r\n  v_student_id text := p_source ->> ''student_id'';\r\n  v_source_section_id text := p_source ->> ''section_id'';\r\n  v_destination_section_id text := p_destination ->> ''section_id'';\r\n  v_source rakeezx.enrollments%rowtype;\r\n  v_destination rakeezx.enrollments%rowtype;\r\n  v_source_section rakeezx.sections%rowtype;\r\n  v_destination_section rakeezx.sections%rowtype;\r\n  v_source_found boolean := false;\r\n  v_destination_found boolean := false;\r\n  v_source_stamp bigint := nullif(p_source ->> ''client_updated_at'', '''')::bigint;\r\n  v_destination_stamp bigint := nullif(p_destination ->> ''client_updated_at'', '''')::bigint;\r\n  v_destination_roll integer := nullif(p_destination ->> ''roll_no'', '''')::integer;\r\nbegin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||'':student-lifecycle-safety'',0));\r\n  if v_owner is null then\r\n    raise exception using errcode = ''42501'', message = ''Authentication required'';\r\n  end if;\r\n  if p_source is null or p_destination is null or\r\n      coalesce(v_source_id, '''') = '''' or coalesce(v_destination_id, '''') = '''' or v_source_id = v_destination_id or\r\n      v_student_id is null or v_student_id = '''' or\r\n      p_destination ->> ''student_id'' is distinct from v_student_id or\r\n      p_source ->> ''status'' is distinct from ''transferred'' or\r\n      p_destination ->> ''status'' is distinct from ''active'' or\r\n      coalesce(v_source_section_id, '''') = '''' or coalesce(v_destination_section_id, '''') = '''' or\r\n      v_source_section_id = v_destination_section_id or\r\n      v_source_stamp is null or v_destination_stamp is null or\r\n      v_destination_roll is null or v_destination_roll not between 1 and 999 then\r\n    raise exception using errcode = ''22023'', message = ''Invalid enrollment transfer payload'';\r\n  end if;\r\n\r\n  -- Serializes competing transfer requests for one student without imposing a\r\n  -- new global active-membership index on uninspected existing production data.\r\n  perform pg_catalog.pg_advisory_xact_lock(\r\n    pg_catalog.hashtextextended(v_owner::text || '':'' || v_student_id, 0));\r\n  -- The source may be historical, but it must still be a section owned by this\r\n  -- caller.  The destination must be an active owned section before either\r\n  -- enrollment row can be changed.\r\n  select * into v_source_section from rakeezx.sections\r\n    where owner_id = v_owner and id = v_source_section_id\r\n    for update;\r\n  if not found then\r\n    raise exception using errcode = ''P0001'', message = ''Source section is not owned by current user'';\r\n  end if;\r\n  select * into v_destination_section from rakeezx.sections\r\n    where owner_id = v_owner and id = v_destination_section_id\r\n    for update;\r\n  if not found or v_destination_section.deleted_at is not null then\r\n    raise exception using errcode = ''P0001'', message = ''Destination section is not active for current user'';\r\n  end if;\r\n\r\n  perform 1 from rakeezx.enrollments\r\n    where owner_id = v_owner and student_id = v_student_id\r\n    for update;\r\n\r\n  select * into v_source from rakeezx.enrollments\r\n    where owner_id = v_owner and id = v_source_id\r\n    for update;\r\n  v_source_found := found;\r\n  select * into v_destination from rakeezx.enrollments\r\n    where owner_id = v_owner and id = v_destination_id\r\n    for update;\r\n  v_destination_found := found;\r\n\r\n  -- IDs are technical identities, not authority to rewrite any owned row.\r\n  -- Existing rows must match every immutable transfer identity in the receipt.\r\n  if (v_source_found and (\r\n        v_source.owner_id is distinct from v_owner or\r\n        v_source.id is distinct from v_source_id or\r\n        v_source.student_id is distinct from v_student_id or\r\n        v_source.section_id is distinct from v_source_section_id\r\n      )) or\r\n      (v_destination_found and (\r\n        v_destination.owner_id is distinct from v_owner or\r\n        v_destination.id is distinct from v_destination_id or\r\n        v_destination.student_id is distinct from v_student_id or\r\n        v_destination.section_id is distinct from v_destination_section_id\r\n      )) then\r\n    raise exception using errcode = ''P0001'', message = ''Enrollment identity does not match transfer payload'';\r\n  end if;\r\n\r\n  if (v_source_found and v_source.deleted_at is not null) or\r\n      (v_destination_found and v_destination.deleted_at is not null) then\r\n    raise exception using errcode = ''P0001'', message = ''Enrollment tombstone cannot be reactivated'';\r\n  end if;\r\n  if (v_source_found and coalesce(v_source.client_updated_at, 0) > v_source_stamp) or\r\n      (v_destination_found and coalesce(v_destination.client_updated_at, 0) > v_destination_stamp) then\r\n    raise exception using errcode = ''P0001'', message = ''Enrollment transfer is stale'';\r\n  end if;\r\n  if exists (\r\n    select 1 from rakeezx.enrollments\r\n      where owner_id = v_owner and student_id = v_student_id and deleted_at is null and status = ''active''\r\n        and id not in (v_source_id, v_destination_id)\r\n  ) then\r\n    raise exception using errcode = ''P0001'', message = ''Another active enrollment already exists'';\r\n  end if;\r\n  if exists (\r\n    select 1 from rakeezx.enrollments\r\n      where owner_id = v_owner and student_id = v_student_id\r\n        and section_id = p_destination ->> ''section_id'' and id <> v_destination_id\r\n  ) then\r\n    raise exception using errcode = ''P0001'', message = ''Destination enrollment identity conflict'';\r\n  end if;\r\n  if exists (\r\n    select 1 from rakeezx.enrollments\r\n      where owner_id = v_owner and section_id = p_destination ->> ''section_id''\r\n        and status = ''active'' and deleted_at is null and roll_no = v_destination_roll\r\n        and id not in (v_source_id, v_destination_id)\r\n  ) then\r\n    raise exception using errcode = ''23505'', message = ''Destination roll number is already active'';\r\n  end if;\r\n\r\n  if v_source_found then\r\n    update rakeezx.enrollments\r\n      set status = ''transferred'',\r\n          end_date = nullif(p_source ->> ''end_date'', '''')::date,\r\n          transfer_note = coalesce(p_source ->> ''transfer_note'', ''''),\r\n          client_updated_at = v_source_stamp,\r\n          device_id = p_source ->> ''device_id''\r\n      where owner_id = v_owner and id = v_source_id\r\n      returning * into v_source;\r\n  else\r\n    insert into rakeezx.enrollments (\r\n      id, student_id, section_id, roll_no, start_date, end_date, status,\r\n      transfer_note, client_updated_at, device_id\r\n    ) values (\r\n      v_source_id, v_student_id, p_source ->> ''section_id'',\r\n      nullif(p_source ->> ''roll_no'', '''')::integer,\r\n      nullif(p_source ->> ''start_date'', '''')::date,\r\n      nullif(p_source ->> ''end_date'', '''')::date,\r\n      ''transferred'', coalesce(p_source ->> ''transfer_note'', ''''),\r\n      v_source_stamp, p_source ->> ''device_id''\r\n    ) returning * into v_source;\r\n  end if;\r\n\r\n  if v_destination_found then\r\n    update rakeezx.enrollments\r\n      set roll_no = v_destination_roll,\r\n          start_date = nullif(p_destination ->> ''start_date'', '''')::date,\r\n          end_date = null,\r\n          status = ''active'',\r\n          client_updated_at = v_destination_stamp,\r\n          device_id = p_destination ->> ''device_id''\r\n      where owner_id = v_owner and id = v_destination_id\r\n      returning * into v_destination;\r\n  else\r\n    insert into rakeezx.enrollments (\r\n      id, student_id, section_id, roll_no, start_date, end_date, status,\r\n      transfer_note, client_updated_at, device_id\r\n    ) values (\r\n      v_destination_id, v_student_id, p_destination ->> ''section_id'',\r\n      v_destination_roll, nullif(p_destination ->> ''start_date'', '''')::date,\r\n      null, ''active'', coalesce(p_destination ->> ''transfer_note'', ''''),\r\n      v_destination_stamp, p_destination ->> ''device_id''\r\n    ) returning * into v_destination;\r\n  end if;\r\n\r\n  return pg_catalog.jsonb_build_object(\r\n    ''source'', pg_catalog.to_jsonb(v_source),\r\n    ''destination'', pg_catalog.to_jsonb(v_destination)\r\n  );\r\nend;\r\n\nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.commit_enrollment_transfer_and_renumber(p_source jsonb, p_destination jsonb, p_source_roster jsonb, p_destination_roster jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\r\ndeclare\r\n  v_owner uuid := auth.uid();\r\n  v_source_id text := p_source ->> ''id'';\r\n  v_destination_id text := p_destination ->> ''id'';\r\n  v_student_id text := p_source ->> ''student_id'';\r\n  v_source_section_id text := p_source ->> ''section_id'';\r\n  v_destination_section_id text := p_destination ->> ''section_id'';\r\n  v_source_stamp bigint := nullif(p_source ->> ''client_updated_at'', '''')::bigint;\r\n  v_destination_stamp bigint := nullif(p_destination ->> ''client_updated_at'', '''')::bigint;\r\n  v_destination_roll integer := nullif(p_destination ->> ''roll_no'', '''')::integer;\r\n  v_source rakeezx.enrollments%rowtype;\r\n  v_destination rakeezx.enrollments%rowtype;\r\n  v_source_found boolean := false;\r\n  v_destination_found boolean := false;\r\n  v_source_plan_count integer;\r\n  v_destination_plan_count integer;\r\n  v_source_active_count integer;\r\n  v_destination_active_count integer;\r\nbegin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||'':student-lifecycle-safety'',0));\r\n  if v_owner is null then\r\n    raise exception using errcode = ''42501'', message = ''Authentication required'';\r\n  end if;\r\n  if pg_catalog.jsonb_typeof(p_source) <> ''object'' or pg_catalog.jsonb_typeof(p_destination) <> ''object'' or\r\n      pg_catalog.jsonb_typeof(p_source_roster) <> ''array'' or pg_catalog.jsonb_typeof(p_destination_roster) <> ''array'' or\r\n      coalesce(v_source_id, '''') = '''' or coalesce(v_destination_id, '''') = '''' or v_source_id = v_destination_id or\r\n      coalesce(v_student_id, '''') = '''' or p_destination ->> ''student_id'' is distinct from v_student_id or\r\n      p_source ->> ''status'' is distinct from ''transferred'' or p_destination ->> ''status'' is distinct from ''active'' or\r\n      coalesce(v_source_section_id, '''') = '''' or coalesce(v_destination_section_id, '''') = '''' or\r\n      v_source_section_id = v_destination_section_id or v_source_stamp is null or v_destination_stamp is null or\r\n      v_destination_roll is null or v_destination_roll not between 1 and 999 then\r\n    raise exception using errcode = ''22023'', message = ''Invalid transfer-and-renumber payload'';\r\n  end if;\r\n\r\n  -- Reject malformed plans before any membership row is changed.  NULL is not\r\n  -- allowed as a final number; it is only an internal, transaction-local step.\r\n  if exists (\r\n    select 1 from pg_catalog.jsonb_array_elements(p_source_roster) as entry(value)\r\n      where pg_catalog.jsonb_typeof(entry.value) is distinct from ''object''\r\n        or coalesce(entry.value ->> ''id'', '''') = ''''\r\n        or pg_catalog.jsonb_typeof(entry.value -> ''roll_no'') is distinct from ''number''\r\n        or not ((entry.value ->> ''roll_no'') ~ ''^[1-9][0-9]{0,2}$'')\r\n        or pg_catalog.jsonb_typeof(entry.value -> ''client_updated_at'') is distinct from ''number''\r\n  ) or exists (\r\n    select 1 from pg_catalog.jsonb_array_elements(p_destination_roster) as entry(value)\r\n      where pg_catalog.jsonb_typeof(entry.value) is distinct from ''object''\r\n        or coalesce(entry.value ->> ''id'', '''') = ''''\r\n        or pg_catalog.jsonb_typeof(entry.value -> ''roll_no'') is distinct from ''number''\r\n        or not ((entry.value ->> ''roll_no'') ~ ''^[1-9][0-9]{0,2}$'')\r\n        or pg_catalog.jsonb_typeof(entry.value -> ''client_updated_at'') is distinct from ''number''\r\n  ) then\r\n    raise exception using errcode = ''22023'', message = ''Invalid final enrollment roster'';\r\n  end if;\r\n\r\n  -- Serialize one student first, then the two sections in a deterministic\r\n  -- order.  This prevents concurrent transfers/renumbers from interleaving.\r\n  perform pg_catalog.pg_advisory_xact_lock(\r\n    pg_catalog.hashtextextended(v_owner::text || '':'' || v_student_id, 0));\r\n  perform pg_catalog.pg_advisory_xact_lock(\r\n    pg_catalog.hashtextextended(v_owner::text || '':section:'' || least(v_source_section_id, v_destination_section_id), 0));\r\n  perform pg_catalog.pg_advisory_xact_lock(\r\n    pg_catalog.hashtextextended(v_owner::text || '':section:'' || greatest(v_source_section_id, v_destination_section_id), 0));\r\n\r\n  perform 1 from rakeezx.sections\r\n    where owner_id = v_owner and id in (v_source_section_id, v_destination_section_id)\r\n    order by id for update;\r\n  if (select count(*) from rakeezx.sections\r\n      where owner_id = v_owner and id in (v_source_section_id, v_destination_section_id)) <> 2 then\r\n    raise exception using errcode = ''P0001'', message = ''Transfer section is not owned by current user'';\r\n  end if;\r\n  if exists (\r\n    select 1 from rakeezx.sections\r\n      where owner_id = v_owner and id = v_destination_section_id and deleted_at is not null\r\n  ) then\r\n    raise exception using errcode = ''P0001'', message = ''Destination section is not active for current user'';\r\n  end if;\r\n\r\n  -- Lock every membership whose state or final number this operation uses.\r\n  perform 1 from rakeezx.enrollments\r\n    where owner_id = v_owner and (student_id = v_student_id or section_id in (v_source_section_id, v_destination_section_id))\r\n    order by section_id, id for update;\r\n\r\n  select * into v_source from rakeezx.enrollments\r\n    where owner_id = v_owner and id = v_source_id;\r\n  v_source_found := found;\r\n  select * into v_destination from rakeezx.enrollments\r\n    where owner_id = v_owner and id = v_destination_id;\r\n  v_destination_found := found;\r\n\r\n  if (v_source_found and (\r\n        v_source.student_id is distinct from v_student_id or v_source.section_id is distinct from v_source_section_id\r\n      )) or (v_destination_found and (\r\n        v_destination.student_id is distinct from v_student_id or v_destination.section_id is distinct from v_destination_section_id\r\n      )) then\r\n    raise exception using errcode = ''P0001'', message = ''Enrollment identity does not match transfer payload'';\r\n  end if;\r\n  if (v_source_found and v_source.deleted_at is not null) or (v_destination_found and v_destination.deleted_at is not null) then\r\n    raise exception using errcode = ''P0001'', message = ''Enrollment tombstone cannot be reactivated'';\r\n  end if;\r\n  if (v_source_found and coalesce(v_source.client_updated_at, 0) > v_source_stamp) or\r\n      (v_destination_found and coalesce(v_destination.client_updated_at, 0) > v_destination_stamp) then\r\n    raise exception using errcode = ''P0001'', message = ''Enrollment transfer is stale'';\r\n  end if;\r\n  if exists (\r\n    select 1 from rakeezx.enrollments\r\n      where owner_id = v_owner and student_id = v_student_id and deleted_at is null and status = ''active''\r\n        and id not in (v_source_id, v_destination_id)\r\n  ) then\r\n    raise exception using errcode = ''P0001'', message = ''Another active enrollment already exists'';\r\n  end if;\r\n  if exists (\r\n    select 1 from rakeezx.enrollments\r\n      where owner_id = v_owner and student_id = v_student_id and section_id = v_destination_section_id\r\n        and id <> v_destination_id\r\n  ) then\r\n    raise exception using errcode = ''P0001'', message = ''Destination enrollment identity conflict'';\r\n  end if;\r\n\r\n  -- First commit membership with no active destination roll.  The final plans\r\n  -- below own every active number, so no intermediate partial-index conflict\r\n  -- can exist even when the student returns to a formerly occupied number.\r\n  if v_source_found then\r\n    update rakeezx.enrollments\r\n      set status = ''transferred'', end_date = nullif(p_source ->> ''end_date'', '''')::date,\r\n          transfer_note = coalesce(p_source ->> ''transfer_note'', ''''),\r\n          client_updated_at = v_source_stamp, device_id = p_source ->> ''device_id''\r\n      where owner_id = v_owner and id = v_source_id\r\n      returning * into v_source;\r\n  else\r\n    insert into rakeezx.enrollments (\r\n      id, student_id, section_id, roll_no, start_date, end_date, status,\r\n      transfer_note, client_updated_at, device_id\r\n    ) values (\r\n      v_source_id, v_student_id, v_source_section_id, nullif(p_source ->> ''roll_no'', '''')::integer,\r\n      nullif(p_source ->> ''start_date'', '''')::date, nullif(p_source ->> ''end_date'', '''')::date,\r\n      ''transferred'', coalesce(p_source ->> ''transfer_note'', ''''), v_source_stamp, p_source ->> ''device_id''\r\n    ) returning * into v_source;\r\n  end if;\r\n\r\n  if v_destination_found then\r\n    update rakeezx.enrollments\r\n      set roll_no = null, start_date = nullif(p_destination ->> ''start_date'', '''')::date,\r\n          end_date = null, status = ''active'', client_updated_at = v_destination_stamp,\r\n          device_id = p_destination ->> ''device_id''\r\n      where owner_id = v_owner and id = v_destination_id\r\n      returning * into v_destination;\r\n  else\r\n    insert into rakeezx.enrollments (\r\n      id, student_id, section_id, roll_no, start_date, end_date, status,\r\n      transfer_note, client_updated_at, device_id\r\n    ) values (\r\n      v_destination_id, v_student_id, v_destination_section_id, null,\r\n      nullif(p_destination ->> ''start_date'', '''')::date, null, ''active'',\r\n      coalesce(p_destination ->> ''transfer_note'', ''''), v_destination_stamp, p_destination ->> ''device_id''\r\n    ) returning * into v_destination;\r\n  end if;\r\n\r\n  select count(*) into v_source_plan_count from pg_catalog.jsonb_to_recordset(p_source_roster)\r\n    as plan(id text, roll_no integer, client_updated_at bigint, device_id text);\r\n  select count(*) into v_destination_plan_count from pg_catalog.jsonb_to_recordset(p_destination_roster)\r\n    as plan(id text, roll_no integer, client_updated_at bigint, device_id text);\r\n  select count(*) into v_source_active_count from rakeezx.enrollments\r\n    where owner_id = v_owner and section_id = v_source_section_id and status = ''active'' and deleted_at is null;\r\n  select count(*) into v_destination_active_count from rakeezx.enrollments\r\n    where owner_id = v_owner and section_id = v_destination_section_id and status = ''active'' and deleted_at is null;\r\n\r\n  if v_source_plan_count <> v_source_active_count or v_destination_plan_count <> v_destination_active_count then\r\n    raise exception using errcode = ''P0001'', message = ''Enrollment roster changed before transfer renumber'';\r\n  end if;\r\n  if exists (\r\n    select 1 from pg_catalog.jsonb_to_recordset(p_source_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)\r\n      left join rakeezx.enrollments enrollment on enrollment.owner_id = v_owner and enrollment.id = plan.id\r\n      where enrollment.id is null or enrollment.section_id <> v_source_section_id or enrollment.status <> ''active'' or\r\n        enrollment.deleted_at is not null or coalesce(enrollment.client_updated_at, 0) > plan.client_updated_at\r\n  ) or exists (\r\n    select 1 from pg_catalog.jsonb_to_recordset(p_destination_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)\r\n      left join rakeezx.enrollments enrollment on enrollment.owner_id = v_owner and enrollment.id = plan.id\r\n      where enrollment.id is null or enrollment.section_id <> v_destination_section_id or enrollment.status <> ''active'' or\r\n        enrollment.deleted_at is not null or coalesce(enrollment.client_updated_at, 0) > plan.client_updated_at\r\n  ) or exists (\r\n    select 1 from (select id from pg_catalog.jsonb_to_recordset(p_source_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) ids group by id having count(*) > 1\r\n  ) or exists (\r\n    select 1 from (select id from pg_catalog.jsonb_to_recordset(p_destination_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) ids group by id having count(*) > 1\r\n  ) or exists (\r\n    select 1 from (select roll_no from pg_catalog.jsonb_to_recordset(p_source_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) rolls group by roll_no having count(*) > 1\r\n  ) or exists (\r\n    select 1 from (select roll_no from pg_catalog.jsonb_to_recordset(p_destination_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) rolls group by roll_no having count(*) > 1\r\n  ) or not exists (\r\n    select 1 from pg_catalog.jsonb_to_recordset(p_destination_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)\r\n      where plan.id = v_destination_id and plan.roll_no = v_destination_roll\r\n  ) then\r\n    raise exception using errcode = ''P0001'', message = ''Invalid or stale final enrollment roster'';\r\n  end if;\r\n\r\n  -- The partial unique index ignores NULL.  Both rosters are clear only\r\n  -- inside this transaction, then receive their complete final sequences.\r\n  update rakeezx.enrollments set roll_no = null\r\n    where owner_id = v_owner and section_id in (v_source_section_id, v_destination_section_id)\r\n      and status = ''active'' and deleted_at is null;\r\n\r\n  update rakeezx.enrollments enrollment\r\n    set roll_no = plan.roll_no, client_updated_at = plan.client_updated_at, device_id = plan.device_id\r\n    from pg_catalog.jsonb_to_recordset(p_source_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)\r\n    where enrollment.owner_id = v_owner and enrollment.id = plan.id;\r\n  update rakeezx.enrollments enrollment\r\n    set roll_no = plan.roll_no, client_updated_at = plan.client_updated_at, device_id = plan.device_id\r\n    from pg_catalog.jsonb_to_recordset(p_destination_roster)\r\n      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)\r\n    where enrollment.owner_id = v_owner and enrollment.id = plan.id;\r\n\r\n  select * into v_source from rakeezx.enrollments where owner_id = v_owner and id = v_source_id;\r\n  select * into v_destination from rakeezx.enrollments where owner_id = v_owner and id = v_destination_id;\r\n  return pg_catalog.jsonb_build_object(\r\n    ''source'', pg_catalog.to_jsonb(v_source),\r\n    ''destination'', pg_catalog.to_jsonb(v_destination),\r\n    ''source_roster'', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.roll_no)\r\n      from rakeezx.enrollments enrollment where owner_id = v_owner and section_id = v_source_section_id\r\n        and status = ''active'' and deleted_at is null), ''[]''::jsonb),\r\n    ''destination_roster'', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.roll_no)\r\n      from rakeezx.enrollments enrollment where owner_id = v_owner and section_id = v_destination_section_id\r\n        and status = ''active'' and deleted_at is null), ''[]''::jsonb)\r\n  );\r\nend;\r\n\nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.provision_account_workspace(p_defaults jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\ndeclare\n  v_owner uuid := auth.uid(); v_profile rakeezx.profile%rowtype;\n  v_year jsonb; v_calendar jsonb; v_subject jsonb; v_row jsonb;\n  v_hash text; v_manifest jsonb; v_preset text; v_expected jsonb; v_normalized jsonb; v_key text;\nbegin\n  if v_owner is null then raise exception using errcode=''42501'', message=''Authentication required''; end if;\n  perform rakeezx.lock_student_lifecycle(v_owner);\n  select * into v_profile from rakeezx.profile where owner_id=v_owner for update;\n  if v_profile.owner_id is null or v_profile.provisioning_state not in (''PROVISIONING'',''READY'') or\n      v_profile.profile_status <> ''READY'' then\n    raise exception using errcode=''42501'', message=''Account provisioning has not begun'';\n  end if;\n  if v_profile.provisioning_state=''READY'' and\n      rakeezx.account_provisioning_foundation_complete(v_owner) then\n    return pg_catalog.jsonb_build_object(''contract'',rakeezx.account_contract(),\n      ''snapshot'',rakeezx.account_provisioning_snapshot());\n  end if;\n  if not exists(select 1 from rakeezx.account_access_grants where owner_id=v_owner and\n      grant_type=''beta_full'' and status=''active'' and (expires_at is null or expires_at > now())) then\n    raise exception using errcode=''42501'', message=''Beta access is required'';\n  end if;\n  -- READY repair is kept behind the original immutable receipt/hash rules.\n  -- Initial provisioning must never retag a previously committed foundation.\n  if v_profile.provisioning_state=''READY'' then\n    return rakeezx.provision_account_workspace_before_n117(p_defaults);\n  end if;\n  if v_profile.education_department is null or not exists(select 1 from rakeezx.education_departments where name=v_profile.education_department) then\n    raise exception using errcode=''22023'', message=''N117_DEPARTMENT_REQUIRED''; end if;\n  v_preset:=case when v_profile.education_department in (''الإدارة العامة للتعليم بمحافظة جدة'',''الإدارة العامة للتعليم بمنطقة المدينة المنورة'',''إدارة التعليم بمحافظة الطائف'',''الإدارة العامة للتعليم بمنطقة مكة المكرمة'') then ''sa-western-1448-1449'' else ''sa-general-1448-1449'' end;\n  v_expected:=case when v_preset=''sa-western-1448-1449'' then $western${"years":[{"id":"y:1448-1449","deleted":false,"label":"1448–1449 هـ","hijriStart":1448,"hijriEnd":1449,"order":1448,"status":"active","calendarPresetId":"sa-western-1448-1449","calendarRegion":"مكة المكرمة • المدينة المنورة • جدة • الطائف","gregorianLabel":"2026–2027 م","startDate":"2026-08-30","endOfYearVacationStart":"2027-07-01","nextAcademicYearStart":"2027-08-29"}],"calendars":[{"id":"cal:y:1448-1449:preset:sa-western-1448-1449","deleted":false,"yearId":"y:1448-1449","source":"preset:sa-western-1448-1449","label":"التقويم المعتمد · 1448–1449 هـ · مكة المكرمة • المدينة المنورة • جدة • الطائف","presetId":"sa-western-1448-1449"}],"terms":[{"id":"tm:y:1448-1449:1","deleted":false,"yearId":"y:1448-1449","name":"الفصل الدراسي الأول","index":1,"startDate":"2026-08-30","endDate":"2027-01-07","status":"active","calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449"},{"id":"tm:y:1448-1449:2","deleted":false,"yearId":"y:1448-1449","name":"الفصل الدراسي الثاني","index":2,"startDate":"2027-01-17","endDate":"2027-07-01","status":"upcoming","calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449"}],"calendarDays":[{"id":"cd:cal:y:1448-1449:preset:sa-western-1448-1449:2026-09-23","deleted":false,"calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449","date":"2026-09-23","kind":"national","label":"إجازة اليوم الوطني","presetId":"sa-western-1448-1449","rangeId":"sa-western-1448-1449:2026-09-23","rangeStart":"2026-09-23","rangeEnd":"2026-09-26"},{"id":"cd:cal:y:1448-1449:preset:sa-western-1448-1449:2026-09-24","deleted":false,"calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449","date":"2026-09-24","kind":"national","label":"إجازة اليوم الوطني","